// SPDX-License-Identifier: MIT
//! Pairwise combinatorial tests over Tier 0's input space.
//!
//! Cases come from `fixtures/combinatorial/tier0-cases.json`, generated by
//! PICT from `tier0.pict`. See that directory's README for why pairwise and why
//! properties rather than golden strings.

use super::*;
use serde::Deserialize;

#[derive(Debug, Deserialize)]
#[serde(rename_all = "PascalCase")]
struct Case {
    language: String,
    filler_class: String,
    position: String,
    stutter: String,
    structure: String,
    punctuation: String,
}

/// Content words per language that are definitely not fillers in that language,
/// so they must survive. Latin script throughout: Tier 0 tokenises on
/// whitespace, which CJK does not use -- those tables are empty stubs and their
/// cases assert pass-through.
fn carrier(lang: &str) -> Vec<&'static str> {
    match lang {
        "de" => vec!["der", "parser", "ist", "gescheitert"],
        "es" => vec!["el", "analizador", "fallo", "hoy"],
        "fr" => vec!["le", "analyseur", "a", "echoue"],
        "it" => vec!["il", "parser", "e", "fallito"],
        "pt" => vec!["o", "analisador", "falhou", "hoje"],
        _ => vec!["the", "parser", "failed", "today"],
    }
}

/// A filler of the requested class for the requested language, or None when
/// that combination has no data.
fn filler(class: &str, lang: &str) -> Option<Vec<&'static str>> {
    match class {
        "always" => Some(vec!["uh"]),
        "gated" => match lang {
            "en" => Some(vec!["um"]),
            "de" => Some(vec!["äh"]),
            "fr" => Some(vec!["euh"]),
            _ => None,
        },
        "initial" => Some(vec!["so"]),
        "phrase" => Some(vec!["you", "know"]),
        _ => None,
    }
}

fn structure_words(s: &str) -> Vec<&'static str> {
    match s {
        "paragraph" => vec!["new", "paragraph"],
        "heading" => vec!["heading"],
        "bullet" => vec!["new", "list"],
        "ordered" => vec!["numbered", "list"],
        _ => vec![],
    }
}

fn normalise(t: &str) -> Vec<String> {
    t.to_lowercase()
        .split(|c: char| !c.is_alphanumeric())
        .filter(|s| !s.is_empty())
        .map(str::to_string)
        .collect()
}

#[test]
fn pairwise_cases_hold_every_tier0_invariant() {
    let raw = include_str!("../../../../fixtures/combinatorial/tier0-cases.json");
    let cases: Vec<Case> = serde_json::from_str(raw).expect("case file must parse");
    assert!(cases.len() >= 40, "suspiciously few cases: {}", cases.len());

    let mut checked = 0usize;
    for (n, c) in cases.iter().enumerate() {
        let lang_opt = if c.language == "unknown" {
            None
        } else {
            Some(c.language.as_str())
        };
        let rules = Tier0Rules::new(lang_opt);
        let carrier = carrier(&c.language);

        // Build the input for this combination.
        let mut words: Vec<String> = structure_words(&c.structure)
            .iter()
            .map(|s| s.to_string())
            .collect();
        let f = filler(&c.filler_class, &c.language);
        let mut body: Vec<String> = Vec::new();
        match (&f, c.position.as_str()) {
            (Some(f), "opening") => {
                body.extend(f.iter().map(|s| s.to_string()));
                body.extend(carrier.iter().map(|s| s.to_string()));
            }
            (Some(f), "mid") => {
                body.push(carrier[0].to_string());
                body.extend(f.iter().map(|s| s.to_string()));
                body.extend(carrier[1..].iter().map(|s| s.to_string()));
            }
            (Some(f), _) => {
                body.extend(carrier.iter().map(|s| s.to_string()));
                body.push("period".into());
                body.extend(f.iter().map(|s| s.to_string()));
                body.extend(carrier.iter().map(|s| s.to_string()));
            }
            _ => body.extend(carrier.iter().map(|s| s.to_string())),
        }
        if c.stutter == "single" {
            body.insert(0, carrier[0].to_string());
            body.insert(0, carrier[0].to_string());
        } else if c.stutter == "multi" {
            let head: Vec<String> = carrier[..2].iter().map(|s| s.to_string()).collect();
            let mut dup = head.clone();
            dup.extend(head);
            dup.extend(body);
            body = dup;
        }
        if c.punctuation == "comma" {
            body.push("comma".into());
        } else if c.punctuation == "period" {
            body.push("period".into());
        }
        words.extend(body);
        let input = words.join(" ");

        let out = rules.process(&input, None);
        let joined = out
            .iter()
            .map(|b| b.text().to_string())
            .collect::<Vec<_>>()
            .join(" ");
        let in_words = normalise(&input);
        let out_words = normalise(&joined);
        let ctx = format!(
            "case {n} [{} {} {} {} {} {}]\n  in : {input}\n  out: {joined}",
            c.language, c.filler_class, c.position, c.stutter, c.structure, c.punctuation
        );

        // P1: Tier 0 is a filter with no generative step. Every output word
        // must have come from the input.
        for w in &out_words {
            assert!(in_words.contains(w), "INVENTED {w:?}\n{ctx}");
        }

        // P2: non-filler content is never dropped.
        for w in &carrier {
            assert!(
                out_words.iter().any(|o| o == w),
                "DROPPED carrier {w:?}\n{ctx}"
            );
        }

        // P3: a sentence-initial word placed mid-sentence must survive --
        // position is the only discriminator, so it has to be load-bearing.
        if c.filler_class == "initial" && c.position == "mid" {
            assert!(
                out_words.iter().any(|o| o == "so"),
                "mid-sentence 'so' removed\n{ctx}"
            );
        }

        // P4: a stub language changes nothing at all.
        if matches!(c.language.as_str(), "ja" | "ko" | "zh" | "yue" | "unknown")
            && c.filler_class == "none"
        {
            assert_eq!(in_words, out_words, "stub language altered text\n{ctx}");
        }
        checked += 1;
    }
    assert_eq!(checked, cases.len());
}
